('4a52b464-4b5b-5aad-badb-3fdb1bb5f3bd', (select id from categories where name = 'Muzîk'), 'ku-kmr', '"Dahol û zirne" bi gelemperî di kîjan rewşê de tên lêxistin?', 'Rêûresma şînê', 'Dersên dibistanê', 'Dawet û govendê', 'Nimêja sibehê', 'C', 'Dahol û zirne bi dengê xwe yê bilind govendê dimeşînin û ahenga reqsê didin. Lewma di dawet û şahiyan de bi hev re tên lêxistin.', 'Dahol û zirne bi dengê xwe yê bilind govendê dimeşînin û ahenga reqsê didin. Lewma di dawet û şahiyan de bi hev re tên lêxistin.', 'Davul ve zurna yüksek sesleriyle halayın temposunu verir ve oyunu yönlendirir. Bu yüzden düğün ve şenliklerde birlikte çalınır.', 2, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0004
