('995a0481-037e-5085-8e0a-cddd43ae2a99', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Radyoya Erîvanê ji bo muzîka kurdî çima girîng e?', 'Bi salan stranên kurdî li seranserê herêmê belav kirin', 'Şêwaza dengî ya bi rîtma azad a ku kilam pê tên gotin', 'Veguhastina muzîkal a bi têkiliya hoste-şagirt', 'Edeta ku ji muzîkjenan re pere tê avêtin', 'A', 'Weşana kurdî ya Radyoya Erîvanê bû çavkaniyeke sereke ya arşîva dengbêjiyê.', 'Weşana kurdî ya Radyoya Erîvanê bû çavkaniyeke sereke ya arşîva dengbêjiyê.', 'Erivan Radyosu 1950''lerden bu yana Kürtçe yayın yaptı; arşivi dengbêj geleneğinin ana kaynağı oldu.', 3, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0017
('db4ac361-7d7d-573f-bcca-0d5d5b96d821', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Peyva "deng" bi Tirkî çi ye?', 'söz', 'ses', 'saz', 'şarkı', 'B', '"Deng" bi Tirkî "ses" e; tiştê ku bi guh tê bihîstin e. Mînak: "Dengê te xweş e."', '"Deng" bi Tirkî "ses" e; tiştê ku bi guh tê bihîstin e. Mînak: "Dengê te xweş e."', '"Deng" Türkçede "ses" demektir; kulakla duyulan şeydir. Örnek: "Dengê te xweş e." (Sesin güzel.)', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0018
('5cd09f02-4513-50bd-843a-3e58be212aa2', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di dengbêjiyê de "kilamên şer" bi giştî li ser çi ne?', 'Avaz û qalibê kilamê', 'Awayê stranbêjiya bi kom', 'Dawet û govendê', 'Bûyerên şer û berxwedanê', 'D', 'Dengbêj di kilamên şer de qala şer, êrîş û berxwedanê dikin. Ev kilam bîra dîrokî ya civakê diparêzin.', 'Dengbêj di kilamên şer de qala şer, êrîş û berxwedanê dikin. Ev kilam bîra dîrokî ya civakê diparêzin.', 'Dengbêjler savaş kilamlarında savaş, saldırı ve direnişi anlatır. Bu kilamlar toplumun tarihî hafızasını korur.', 5, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0019
('ae0164d2-e1b7-5afa-9d16-40d9824eeb97', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Rast e an şaş e: Def û erbane herdu jî amûrên lêdanê ne.', 'Rast', 'Şaş', '-', '-', 'A', 'Herdu jî bi çerm têne çêkirin û bi lêdanê deng didin.', 'Herdu jî bi çerm têne çêkirin û bi lêdanê deng didin.', 'İkisi de deri kaplıdır ve vurularak ses verir.', 4, true, 'true_false', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0020
('af1eaf1f-e95b-52ec-980f-39bcca64bf67', (select id from categories where name = 'Muzîk'), 'ku-kmr', '"Şeştar" an amûrên têlî yên kurdî bi giştî çawa tên lêxistin?', 'Dawet û govendê', 'Koma stranbêj û muzîkjenan', 'Awayê stranbêjiya bi kom', 'Bi tiliyan an bi mizrabê', 'D', 'Şeştar, tembûr û saz amûrên têlî ne û bi tiliyan an bi mizrabê tên lêxistin. Bi lêxistina têlan deng çêdibe.', 'Şeştar, tembûr û saz amûrên têlî ne û bi tiliyan an bi mizrabê tên lêxistin. Bi lêxistina têlan deng çêdibe.', 'Şeştar, tembûr ve saz telli çalgılardır; parmakla ya da mızrapla çalınır. Tellere vurularak ses çıkarılır.', 3, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0021
('11c13413-34c1-51c0-a013-04d51b0a0159', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di muzîka kurdî de peyva "stranbêj" ji bo kê tê bikaranîn?', 'Kesê ku amûrê çêdike', 'Kesê ku reqsê hîn dike', 'Kesê ku stranan dibêje', 'Kesê ku helbestê dinivîse', 'C', '"Stranbêj" ji "stran" û "bêj" (gotin) pêk tê.', '"Stranbêj" ji "stran" û "bêj" (gotin) pêk tê.', '"Stranbêj", "stran" ve "bêj" (söylemek) sözcüklerinden oluşur.', 2, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0022
('d1762212-4e25-5cc0-bf5c-e9225ed77b8d', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di muzîka kurdî de "makam" an "avaz" çi diyar dike?', 'Hejmara stranbêjan', 'Dirêjahiya dawetê', 'Navê amûrê', 'Qalibê dengî yê stranê', 'D', 'Avaz qalibê makamî ye ku stran li ser tê avakirin.', 'Avaz qalibê makamî ye ku stran li ser tê avakirin.', 'Avaz, şarkının üzerine kurulduğu makam kalıbıdır.', 4, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0023
('77a4ed58-65d3-574f-913d-ff25b6c36db1', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di dawetên kurdî de reqsa komî bi gelemperî bi kîjan amûran tê meşandin?', 'Tembûr û bilûr', 'Dahol û zirne', 'Piano û gîtar', 'Erbane û ney', 'B', 'Di dawetên kurdî de govend bi dahol û zirneyê tê meşandin. Dengê wan ê bilind ji bo reqsa komî ya li derve guncav e.', 'Di dawetên kurdî de govend bi dahol û zirneyê tê meşandin. Dengê wan ê bilind ji bo reqsa komî ya li derve guncav e.', 'Kürt düğünlerinde halay davul ve zurnayla yürütülür. Yüksek sesleri açık havadaki toplu dansa uygundur.', 3, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0024
('f1ae8d02-3ffe-5c2b-9c0d-86a7875709cc', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di kilamên dengbêjan de "vegotin" çima girîng e?', 'Tenê ahenga dengî girîng e', 'Reqs pê re tê kirin', 'Amûr pê re tên lêxistin', 'Kilam çîrokeke dîrokî diguhezîne', 'D', 'Dengbêjî hem muzîk hem arşîva devkî ye: bûyer bi kilamê tên parastin.', 'Dengbêjî hem muzîk hem arşîva devkî ye: bûyer bi kilamê tên parastin.', 'Dengbêjlik hem müzik hem sözlü arşivdir: olaylar kilamla korunur.', 5, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0025
('73cefd1f-d298-5fb3-a436-1a3e04fcc2c3', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Peyva "kilam" bi Tirkî bi giştî tê wateya çi?', 'dans', 'saz', 'türkü', 'düğün', 'C', '"Kilam" stranên dirêj ên çîrokî ne.', '"Kilam" stranên dirêj ên çîrokî ne.', '"Kilam", hikâye anlatan uzun ezgilerdir.', 2, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0026
('6eee6d0d-3636-5701-8498-a6da5c3a5f83', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di muzîka kurdî ya nûjen de "kom" çi ye?', 'Bûyerên şer û berxwedanê', 'Stranên kurt ên bi gelemperî evîndar', 'Kilam çîrokeke dîrokî diguhezîne', 'Koma stranbêj û muzîkjenan', 'D', '"Kom" bi hev re distirên û dilîzin; muzîka komî ya salên 1990î pê tê nasîn.', '"Kom" bi hev re distirên û dilîzin; muzîka komî ya salên 1990î pê tê nasîn.', '"Kom", birlikte söyleyip çalan topluluktur; 1990''ların toplu müziği bununla anılır.', 4, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0027
('96df0611-f642-505b-aa96-85f857184fb2', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Rast e an şaş e: Bilûr bi pifê tê lêxistin.', 'Rast', 'Şaş', '-', '-', 'A', 'Bilûr amûreke pifê ye.', 'Bilûr amûreke pifê ye.', 'Kaval üflemeli bir çalgıdır.', 3, true, 'true_false', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0028
('61510f10-ead1-5962-ad7c-30f4764671f5', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di dengbêjiyê de "şêwe" ya herêmî çi tê wateyê?', 'cureyekî kilamê yê bi gelemperî evîndar', 'kesê ku bi giştî stranan dibêje', 'awayê gotinê yê taybetî yê herêmekê', 'edeta ku ji muzîkjenan re pere tê avêtin', 'C', 'Her herêm — Serhed, Botan, Behdînan — şêwazeke dengbêjiyê ya xwe heye.', 'Her herêm — Serhed, Botan, Behdînan — şêwazeke dengbêjiyê ya xwe heye.', 'Her yöre — Serhed, Botan, Behdinan — kendi dengbêj üslubuna sahiptir.', 5, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0029
('0539b632-d722-54ea-bfd3-5dc205f12057', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di stranên zarokan ên kurdî de "lorî" çi ye?', 'Strana dawetê', 'Kilama şer', 'Strana cejnê', 'Strana razanê', 'D', 'Lorî ji bo razandina zarokan tê gotin.', 'Lorî ji bo razandina zarokan tê gotin.', 'Lorî (ninni), çocuğu uyutmak için söylenir.', 3, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0030
('4beac4a5-b058-5533-9ddd-56acaace8a54', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Muzîka kurdî ya diasporayê bi giştî çi bandor kir?', 'Komên muzîka kurdî ya nûjen', 'veguhastina muzîkal a bi têkiliya hoste-şagird', 'Belavbûna cîhanî ya stran û tomarkirinê', 'muzîka rîtmîk û makamî ya herêma Şirnex û Cizîrê', 'C', 'Diasporayê studyo, weşan û festîvalên nû anîn; stran li cîhanê belav bûn.', 'Diasporayê studyo, weşan û festîvalên nû anîn; stran li cîhanê belav bûn.', 'Diaspora yeni stüdyo, yayın ve festivaller getirdi; şarkılar dünyaya yayıldı.', 4, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0031
('bf12ed62-db28-5a6d-b769-38b1e430e34b', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Peyva "govend" bi Tirkî çi ye?', 'şarkı', 'saz', 'düğün', 'halay', 'D', 'Govend lîstikeke komî ye ku bi girtina destan tê lîstin; bi Tirkî jê re "halay" tê gotin.', 'Govend lîstikeke komî ye ku bi girtina destan tê lîstin; bi Tirkî jê re "halay" tê gotin.', 'Govend, el ele tutuşarak grup hâlinde oynanan halk oyunudur; Türkçedeki karşılığı "halay"dır.', 2, true, 'multiple_choice', NULL, NULL, 'Muzîk û dengbêjiya kurdî', 'Mehmet Uzun, Dengbêj Üslubu Hakkında; Estelle Amy de la Bretèque, Paroles mélodisées (2013)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_muzik_0032
('ff461809-752e-5ed2-af48-d8f337528df8', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Kîjan helbestvanî ji Şivan Perwer re gotiye "dengê helbestên min"?', 'Qedrîcan', 'Cegerxwîn', 'Osman Sebrî', 'Arjen Arî', 'B', 'Şivan Perwer gelek helbestên Cegerxwîn kirine stran û bi dengê xwe belav kirine; lewma Cegerxwîn ew wek dengê helbestên xwe didît.', 'Şivan Perwer gelek helbestên Cegerxwîn kirine stran û bi dengê xwe belav kirine; lewma Cegerxwîn ew wek dengê helbestên xwe didît.', 'Şivan Perwer, Cegerxwîn''in birçok şiirini besteleyip seslendirmiştir; bu yüzden Cegerxwîn onu şiirlerinin sesi olarak görmüştür.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/%C5%9Eivan_Perwer', 'Şivan Perwer - Wikipedia (English)', 'https://en.wikipedia.org/wiki/%C5%9Eivan_Perwer', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_001
('057c3354-f2aa-5909-a2e4-31bc5bd8bf88', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Ciwan Haco sala 2012an "Esmer" bi kîjan hunermenda navdar a Tirkiyeyê re got?', 'Sibel Can', 'Sezen Aksu', 'Ajda Pekkan', 'Hülya Avşar', 'D', 'Strana Esmer wek dueteke Ciwan Haco û Hülya Avşar hat belavkirin.', 'Strana Esmer wek dueteke Ciwan Haco û Hülya Avşar hat belavkirin.', 'Esmer şarkısı Ciwan Haco ile Hülya Avşar''ın düeti olarak yayımlandı.', 2, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Ciwan_Haco', 'Ciwan Haco - Vikipedi (Türkçe)', 'https://tr.wikipedia.org/wiki/Ciwan_Haco', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_002
('ddcfefbe-787d-5be7-b4a8-c9123547332b', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Aynur Dogan li kîjan parêzgehê ji dayik bûye?', 'Bedlîs', 'Erzirom', 'Dêrsim', 'Mûş', 'C', 'Aynur Dogan sala 1975an li navçeya Çemişgezekê ya Dêrsimê hatiye dinyayê û di 1992an de çû Stenbolê.', 'Aynur Dogan sala 1975an li navçeya Çemişgezekê ya Dêrsimê hatiye dinyayê û di 1992an de çû Stenbolê.', 'Aynur Doğan 1975''te Tunceli''nin Çemişgezek ilçesinde doğdu ve 1992''de İstanbul''a taşındı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Aynur_Do%C4%9Fan', 'Aynur Doğan - Wikipedia (English)', 'https://en.wikipedia.org/wiki/Aynur_Do%C4%9Fan', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_003
('8b2415ea-b7ec-5724-9556-418b4b16a4a9', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Aram Tigran ji sala 1966an pê ve bi salan li kîjan radyoyê xebitî?', 'Radyoya Bexdayê', 'Radyoya Tehranê', 'Radyoya Qahîreyê', 'Radyoya Erîvanê', 'D', 'Radyoya Erîvanê di parastina muzîk û çanda kurdî de xwedî roleke dîrokî ye. Aram Tigran bi salan di beşa kurdî ya vê radyoyê de xebitî.', 'Radyoya Erîvanê di parastina muzîk û çanda kurdî de xwedî roleke dîrokî ye. Aram Tigran bi salan di beşa kurdî ya vê radyoyê de xebitî.', 'Erivan Radyosu, Kürt müzik ve kültürünün korunmasında tarihî bir role sahiptir. Aram Tigran yıllarca bu radyonun Kürtçe bölümünde çalıştı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Aram_Tigran', 'Aram Tigran - Wikipedia (English)', 'https://en.wikipedia.org/wiki/Aram_Tigran', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_004
('e52fcda5-0875-5764-8ee2-24db1241370b', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Şivan Perwer sala 1976an li kîjan welatî bi cih bû?', 'Awistirya', 'Almanya', 'Fransa', 'Hollanda', 'B', 'Şivan Perwer di 1976an de li Almanyayê bi cih bû û albûma xwe ya fermî ya yekem a stranên gelêrî li wir tomar kir.', 'Şivan Perwer di 1976an de li Almanyayê bi cih bû û albûma xwe ya fermî ya yekem a stranên gelêrî li wir tomar kir.', 'Şivan Perwer 1976''da Almanya''ya yerleşti ve halk şarkılarından oluşan ilk resmî albümünü orada kaydetti.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/%C5%9Eivan_Perwer', 'Şivan Perwer - Wikipedia (English)', 'https://en.wikipedia.org/wiki/%C5%9Eivan_Perwer', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_005
('9268e5e6-4f2f-5b9f-9b01-b50679818e23', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Aynur Dogan di kîjan fîlmê Yavuz Turgul de bi straneke kurdî xuya bû?', 'Gölge Oyunu', 'Eşkıya', 'Muhsin Bey', 'Gönül Yarası', 'D', 'Aynur di "Gönül Yarası" de di roleke biçûk de wek xwe xuya bû û strana "Dar Hejîrokê" got; bi vê yekê guhdarên tirk jî ew nas kirin.', 'Aynur di "Gönül Yarası" de di roleke biçûk de wek xwe xuya bû û strana "Dar Hejîrokê" got; bi vê yekê guhdarên tirk jî ew nas kirin.', 'Aynur "Gönül Yarası"nda kendisi olarak küçük bir rolde göründü ve "Dar Hejiroke"yi söyledi; bu sayede Türk dinleyiciler de onu tanıdı.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Aynur_Do%C4%9Fan', 'Aynur Doğan - Wikipedia (English)', 'https://en.wikipedia.org/wiki/Aynur_Do%C4%9Fan', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_006
('1c88cd48-ef36-5c4a-ba54-4fe8f620c609', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di albûma Ciwan Haco ya "Off" (2006) de, "Li hêviya te" ji bilî kurdî bi kîjan zimanî jî tê gotin?', 'Îngilîzî', 'Swêdî', 'Fransî', 'Almanî', 'C', 'Strana sereke ya albûma "Off" hem bi kurdî hem bi fransî ye; beşa fransî ji aliyê hunermendeke jin ve tê gotin.', 'Strana sereke ya albûma "Off" hem bi kurdî hem bi fransî ye; beşa fransî ji aliyê hunermendeke jin ve tê gotin.', '"Off" albümünün ana şarkısı hem Kürtçe hem Fransızca söylenir; Fransızca bölümü bir kadın vokal seslendirir.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ciwan_Haco', 'Ciwan Haco - Wikipedia (English)', 'https://en.wikipedia.org/wiki/Ciwan_Haco', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_007
('e28d2136-9f7d-5520-9616-deafee17dd57', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Albûma solo ya yekem a stranbêj Rojdayê kîjan e?', 'Kezî', 'Stranên Bijartî', 'Bazin', 'Sebra Min', 'D', 'Rojda berê bi Koma Gulên Xerzan re stran digot; albûma xwe ya solo ya yekem "Sebra Min" di sala 2006an de weşand.', 'Rojda berê bi Koma Gulên Xerzan re stran digot; albûma xwe ya solo ya yekem "Sebra Min" di sala 2006an de weşand.', 'Rojda önce Koma Gulên Xerzan ile söyledi; ilk solo albümü "Sebra Min"i 2006''da yayımladı.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rojda', 'Rojda - Wikipedia (English)', 'https://en.wikipedia.org/wiki/Rojda', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_008
('b6fdcf10-239e-5c70-bee9-d54b990e0056', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Xêro Abbas di sala 1998an de albûma xwe ya yekem bi kîjan navî weşand?', 'Axîn', 'Xerîbo', 'Zorê', 'Dilava', 'B', 'Xêro Abbas, ku sala 1962an li Qamişloyê hatiye dinyayê, kariyera xwe ya muzîkê bi albûma "Xerîbo" dest pê kir û ev albûm di nav kurdan de pir hat hezkirin.', 'Xêro Abbas, ku sala 1962an li Qamişloyê hatiye dinyayê, kariyera xwe ya muzîkê bi albûma "Xerîbo" dest pê kir û ev albûm di nav kurdan de pir hat hezkirin.', '1962''de Kamışlı''da doğan Xêro Abbas müzik kariyerine "Xerîbo" albümüyle başladı ve bu albüm Kürtler arasında çok sevildi.', 3, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/X%C3%AAro_Abbas', 'Xêro Abbas - Wîkîpediya (Kurmancî)', 'https://ku.wikipedia.org/wiki/X%C3%AAro_Abbas', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_009
('79bda887-7b16-567c-9fc6-d1069f6430bd', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Hozan Kawa bi albûma xwe ya sala 2001ê hat naskirin. Navê wê albûmê çi ye?', 'Ez û Tu', 'Taya Dila', 'Ava Evînê', 'Tava Hîvê', 'C', 'Hozan Kawa, ku sala 1972an li Palasa Mûşê ji dayik bûye, bi albûma "Ava Evînê" navdar bû; paşê albûmên wek "Taya Dila" û "Şeng" jî derxistin.', 'Hozan Kawa, ku sala 1972an li Palasa Mûşê ji dayik bûye, bi albûma "Ava Evînê" navdar bû; paşê albûmên wek "Taya Dila" û "Şeng" jî derxistin.', '1972''de Muş''a bağlı Palas''ta doğan Hozan Kawa "Ava Evînê" albümüyle ünlendi; ardından "Taya Dila" ve "Şeng" gibi albümler çıkardı.', 2, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Hozan_Kawa', 'Hozan Kawa - Wîkîpediya (Kurmancî)', 'https://ku.wikipedia.org/wiki/Hozan_Kawa', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_010
('7cefa4c2-c9b3-53bd-b1dc-624e1e945178', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Mehmet Atli ji bilî muzîkê wek çi jî dixebite?', 'Mîmar', 'Pîlot', 'Rojnamevan', 'Bijîşk', 'A', 'Mehmet Atli beşa mîmariyê ya Zanîngeha Teknîkî ya Yildizê qedand, li Zanîngeha Artukluyê ya Mêrdînê mamostetiya mîmariyê kir û niha jî hem mîmariyê hem muzîkê didomîne.', 'Mehmet Atli beşa mîmariyê ya Zanîngeha Teknîkî ya Yildizê qedand, li Zanîngeha Artukluyê ya Mêrdînê mamostetiya mîmariyê kir û niha jî hem mîmariyê hem muzîkê didomîne.', 'Mehmet Atlı Yıldız Teknik Üniversitesi Mimarlık Bölümü''nü bitirdi, Mardin Artuklu Üniversitesi''nde mimarlık dersleri verdi ve mimarlıkla müziği birlikte sürdürüyor.', 4, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Mehmet_Atl%C4%B1', 'Mehmet Atlı - Vikipedi (Türkçe)', 'https://tr.wikipedia.org/wiki/Mehmet_Atl%C4%B1', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_011
('4b7d0576-ad8f-519d-9b23-bf0988f93d2f', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Aynur Dogan sala 2021ê xelata hunermendê ya kîjan fuara muzîkê ya navneteweyî wergirt?', 'MIDEM', 'Eurosonic', 'Musikmesse', 'WOMEX', 'D', 'WOMEX fuara navneteweyî ya muzîka cîhanê ye. Aynur Dogan di 2021ê de Xelata Hunermendê ya WOMEXê wergirt.', 'WOMEX fuara navneteweyî ya muzîka cîhanê ye. Aynur Dogan di 2021ê de Xelata Hunermendê ya WOMEXê wergirt.', 'WOMEX uluslararası dünya müziği fuarıdır. Aynur Doğan 2021''de WOMEX Sanatçı Ödülü''nü aldı.', 5, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Aynur_Do%C4%9Fan', 'Aynur Doğan - Vikipedi (Türkçe)', 'https://tr.wikipedia.org/wiki/Aynur_Do%C4%9Fan', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_012
('272611e7-f47f-58de-b5ae-f711deec7639', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Grûpa Kardeş Türküler di sala 1993an de ji aliyê xwendekarên kîjan zanîngehê ve hate damezrandin?', 'Zanîngeha Boğaziçiyê', 'Zanîngeha Enqereyê', 'Zanîngeha Dîcleyê', 'Zanîngeha Teknîk a Stenbolê', 'A', 'Kardeş Türküler wek projeya Klûba Folklorê ya Zanîngeha Boğaziçiyê dest pê kir. Kom bi stranên pirzimanî tê nasîn.', 'Kardeş Türküler wek projeya Klûba Folklorê ya Zanîngeha Boğaziçiyê dest pê kir. Kom bi stranên pirzimanî tê nasîn.', 'Kardeş Türküler, Boğaziçi Üniversitesi Folklor Kulübü''nün bir projesi olarak başladı. Topluluk çok dilli şarkılarıyla tanınır.', 1, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Karde%C5%9F_T%C3%BCrk%C3%BCler', 'Kardeş Türküler - Vikipedi', 'https://tr.wikipedia.org/wiki/Karde%C5%9F_T%C3%BCrk%C3%BCler', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_013
('b0cd8636-97f7-5604-8dbb-144f9696f9e1', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Grûpa Kardeş Türküler rêvebiriya muzîkê û aranjmanên kîjan albûma Şivan Perwer a sala 2000î kirin?', 'Dotmam', 'Zembîlfiroş', 'Roj û Heyv', 'Hêviya Te', 'C', '"Roj û Heyv" albûma Şivan Perwer a sala 2000î ye; rêvebiriya muzîkê û aranjmanên wê endamên Kardeş Türküler kirin. Grûpê paşê muzîka fîlmê "Vizontele" jî amade kir.', '"Roj û Heyv" albûma Şivan Perwer a sala 2000î ye; rêvebiriya muzîkê û aranjmanên wê endamên Kardeş Türküler kirin. Grûpê paşê muzîka fîlmê "Vizontele" jî amade kir.', '"Roj û Heyv", Şivan Perwer''in 2000 yılında çıkan albümüdür; müzik yönetmenliğini ve düzenlemelerini Kardeş Türküler kadrosu yaptı. Grup daha sonra "Vizontele" filminin müziklerini de hazırladı.', 3, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Karde%C5%9F_T%C3%BCrk%C3%BCler', 'Kardeş Türküler - Vikipedi', 'https://tr.wikipedia.org/wiki/Karde%C5%9F_T%C3%BCrk%C3%BCler', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_014
('d2eab631-2085-5baf-bb22-372b40ac61c5', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Koma Wetan, yekem grûpa rockê ya kurdî, li kîjan bajarî hate damezrandin?', 'Tiflîs', 'Yêrêvan', 'Mosko', 'Bakû', 'A', 'Koma Wetan li Tiflîsê, paytexta Gurcistana Sovyetê ya wê demê, ji aliyê çar ciwanan ve hate avakirin. Wan helbestên helbestvanên kurd ên Qefqasyayê bi muzîka rockê kirin stran.', 'Koma Wetan li Tiflîsê, paytexta Gurcistana Sovyetê ya wê demê, ji aliyê çar ciwanan ve hate avakirin. Wan helbestên helbestvanên kurd ên Qefqasyayê bi muzîka rockê kirin stran.', 'Koma Wetan, o dönem Sovyetler Birliği''ne bağlı Gürcistan''ın başkenti Tiflis''te dört genç tarafından kuruldu. Grup, Kafkasyalı Kürt şairlerin şiirlerini rock müziğe uyarladı.', 2, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Koma_Wetan', 'Koma Wetan - Vikipedi', 'https://tr.wikipedia.org/wiki/Koma_Wetan', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_015
('5902e7d8-0111-50d5-9f8f-a6a8a3df2f49', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Albûma grûpa Koma Wetan a sala 1989an ji aliyê kîjan şîrketa plakan ve hate weşandin?', 'Kom Müzik', 'Ses Plak', 'Kalan Müzik', 'Melodiya', 'D', 'Melodiya şîrketa plakan a dewletê ya Yekîtiya Sovyetê bû. Loma bersiva rast Melodiya ye.', 'Melodiya şîrketa plakan a dewletê ya Yekîtiya Sovyetê bû. Loma bersiva rast Melodiya ye.', 'Melodiya, Sovyetler Birliği''nin devlet plak şirketiydi. Bu yüzden doğru cevap Melodiya''dır.', 4, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Koma_Wetan', 'Koma Wetan - Vikipedi', 'https://tr.wikipedia.org/wiki/Koma_Wetan', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_016
('67d1d5fd-b0cd-543d-ac4f-2fe2a52f2a6a', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Grûpa malbatî ya Kamkaran ji çend bira û xwişkan pêk tê?', 'Heft bira û xwişkek', 'Pênc bira û du xwişk', 'Çar bira û sê xwişk', 'Şeş bira û xwişkek', 'A', 'Kamkaran komeke malbatî ye; heft bira û xwişkek bi hev re muzîkê çêdikin.', 'Kamkaran komeke malbatî ye; heft bira û xwişkek bi hev re muzîkê çêdikin.', 'Kamkarlar bir aile topluluğudur; yedi erkek kardeş ve bir kız kardeş birlikte müzik yapar.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Kamkars', 'The Kamkars - Wikipedia', 'https://en.wikipedia.org/wiki/The_Kamkars', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_017
('69b8740f-4311-52a5-bf60-a5849572d889', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Grûpa muzîkê ya Kamkaran di sala 2003an de li merasîma kîjan xelatê konser da?', 'Xelata Grammyê', 'Xelata Oscarê', 'Xelata Nobelê ya Aştiyê', 'Xelata Muzîkê ya Polar a Swêdê', 'C', 'Koma Kamkaran di merasîma Xelata Nobelê ya Aştiyê ya 2003an de derket ser dikê. Ew xelat wê salê ji Şîrîn Ebadî re hatibû dayîn.', 'Koma Kamkaran di merasîma Xelata Nobelê ya Aştiyê ya 2003an de derket ser dikê. Ew xelat wê salê ji Şîrîn Ebadî re hatibû dayîn.', 'Kamkarlar topluluğu 2003 Nobel Barış Ödülü töreninde sahneye çıktı. O yılki ödül Şirin Ebadi''ye verilmişti.', 4, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Kamkars', 'The Kamkars - Wikipedia', 'https://en.wikipedia.org/wiki/The_Kamkars', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_018
('1a9f2937-a495-53a1-8b8d-0d8f1ee3abfc', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Navê kîjan grûpa folk-rockê peyveke kurdî ye ku bi tirkî tê wateya "şehir"?', 'Bajar', 'Kamkaran', 'Koma Wetan', 'Çar Newa', 'A', 'Navê komê peyva kurdî "bajar" e, ku wateya wê ya tirkî "şehir" e. Kom bi kurdî, zazakî û tirkî stranên folk-rockê dibêje.', 'Navê komê peyva kurdî "bajar" e, ku wateya wê ya tirkî "şehir" e. Kom bi kurdî, zazakî û tirkî stranên folk-rockê dibêje.', 'Grubun adı Kürtçede şehir anlamına gelen Bajar sözcüğüdür. Grup Kürtçe, Zazaca ve Türkçe folk rock şarkıları söyler.', 1, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Bajar', 'Bajar - Vikipedi', 'https://tr.wikipedia.org/wiki/Bajar', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_019
('a3052e26-41dc-5aed-b428-5e32b531207b', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Şîrketa "Kalan Müzik", ku gelek albûmên muzîka kurdî weşandine, di sala 1991ê de ji aliyê kê ve hate damezrandin?', 'Naim Dilmener', 'Hasan Saltık', 'Erkan Oğur', 'Ömer Faruk Kurhan', 'B', 'Hasan Saltık damezrînerê Kalan Müzikê ye. Ev şîrket bi arşîvkirina muzîka gelêrî tê nasîn.', 'Hasan Saltık damezrînerê Kalan Müzikê ye. Ev şîrket bi arşîvkirina muzîka gelêrî tê nasîn.', 'Hasan Saltık, Kalan Müzik''in kurucusudur. Şirket halk müziği arşiviyle tanınır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kalan_M%C3%BCzik', 'Kalan Müzik - Wikipedia', 'https://en.wikipedia.org/wiki/Kalan_M%C3%BCzik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_020
('9b432dc4-a3a2-5837-b4c9-e0684f5a92b2', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Grûpa Şems (Shamss Ensemble), ku muzîka sûfî û kurdî pêşkêş dike, ji aliyê kîjan bestekarî ve hate damezrandin?', 'Keyxusro Pûrnazerî', 'Kayhan Kalhor', 'Mihemedreza Derwîşî', 'Hûşeng Kamkar', 'A', 'Koma Şems muzîka tesewufî pêşkêş dike. Keyxusro Pûrnazerî ev kom ava kiriye.', 'Koma Şems muzîka tesewufî pêşkêş dike. Keyxusro Pûrnazerî ev kom ava kiriye.', 'Şems Topluluğu tasavvuf müziği icra eder. Topluluğu Keyhüsrev Purnazeri kurmuştur.', 5, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Shamss_Ensemble', 'Shamss Ensemble - Wikipedia', 'https://en.wikipedia.org/wiki/Shamss_Ensemble', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_021
('27f79ef7-40de-5a9f-9e28-5178363a7c3e', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Grûpa Kardeş Türküler bi albûma xwe ya duyem a sala 1999an navdar bû. Navê wê albûmê çi ye?', 'Bahar', 'Doğu', 'Yol', 'Hemâvâz', 'B', 'Albûma "Doğu" (1999) awazên rojhilatê Anadoluyê û Mezopotamyayê dihewîne û navê grûpê li Tirkiyeyê û li derve belav kir. Piştî wê konserên grûpê yên li Harbiyeyê bûn kevneşopî.', 'Albûma "Doğu" (1999) awazên rojhilatê Anadoluyê û Mezopotamyayê dihewîne û navê grûpê li Tirkiyeyê û li derve belav kir. Piştî wê konserên grûpê yên li Harbiyeyê bûn kevneşopî.', '"Doğu" (1999) Doğu Anadolu ve Mezopotamya''dan ezgiler içerir ve grubun adını yurt içinde ve dışında duyurdu. Ardından grubun Harbiye konserleri gelenekselleşti.', 3, true, 'multiple_choice', NULL, 'https://tr.wikipedia.org/wiki/Karde%C5%9F_T%C3%BCrk%C3%BCler', 'Kardeş Türküler - Vikipedi', 'https://tr.wikipedia.org/wiki/Karde%C5%9F_T%C3%BCrk%C3%BCler', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_nujen_022
('b8878786-0fa1-5fa9-8470-65a6c5566433', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di muzîka kurdî de rîtm bi çi re têkildar e?', 'bilindbûna dengê stranê', 'lêdana rêkûpêk', 'hejmara amûrên di komê de', 'dirêjahiya stranê', 'B', 'Rîtm lêdana rêkûpêk e: dem li perçeyên wekhev tê parvekirin û stran û govend li ser vê parvekirinê tên avakirin. Di muzîka kurdî de dahol vê lêdanê diyar dike û govend li gorî wê tê gerandin.', 'Rîtm lêdana rêkûpêk e: dem li perçeyên wekhev tê parvekirin û stran û govend li ser vê parvekirinê tên avakirin. Di muzîka kurdî de dahol vê lêdanê diyar dike û govend li gorî wê tê gerandin.', 'Ritim düzenli vuruştur: zaman eşit parçalara bölünür ve şarkı ile halay bu bölünmenin üzerine kurulur. Kürt müziğinde bu vuruşu çoğunlukla davul belirler, halay da ona göre oynanır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_0873
('b6180e9e-1460-56fd-b07f-409fcd93dc3c', (select id from categories where name = 'Muzîk'), 'ku-kmr', '"awazên Serhedê" çi ne?', 'muzîka rîtmîk û makamî ya herêma Şirnex û Cizîrê', 'şêwaza muzîka lîrîk a taybetî ya herêma Qersê, Agirî û Wanê', 'dengbêjê bi eslê xwe ermenî yê ku muzîka devkî ya kurdî berhev kir', 'hunermendê rîtmê yê ku erbane an defê bi hostatî lê dide', 'B', '"awazên Serhedê": şêwaza muzîka lîrîk a taybetî ya devera Qers, Agirî û Wanê.', '"awazên Serhedê": şêwaza muzîka lîrîk a taybetî ya devera Qers, Agirî û Wanê.', '"serhad ezgileri": Kars, Ağrı ve Van yöresine özgü lirik müzik tarzı.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_10314
('11a79256-9ebb-5b2a-8cf5-10c39409d74b', (select id from categories where name = 'Muzîk'), 'ku-kmr', '"dibistana dengbêjiyê" çi ye?', 'veguhastina muzîkal a bi têkiliya hoste-şagirt', 'muzîka devkî ya ku di şevbihêrkên zivistanê de tê gotin', 'erbaneya bi zil a ku di muzîka gelêrî de pir tê lêxistin', 'şêwaza muzîka lîrîk a taybetî ya herêma Qersê, Agirî û Wanê', 'A', '"dibistana dengbêjiyê": veguhastina muzîkî ya bi têkiliya hoste-şagirt.', '"dibistana dengbêjiyê": veguhastina muzîkî ya bi têkiliya hoste-şagirt.', '"dengbêjlik okulu": usta-çırak ilişkisiyle yürüyen müzikal aktarım.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_10320
