('3d29e580-9e55-56fc-b738-071562af70cf', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Dengbêjê mezin ê bi dengê bêhempa, "Şahê Dengbêjan" kî bû?', 'Şakiro', 'lîrîka klaman', 'bilûr', 'Meryem Xan', 'A', '"Şakiro" tê vê wateyê: dengbêjê mezin ê ku wekî "Şahê Dengbêjan" tê naskirin û xwedî dengekî bêhempa bû.', '"Şakiro" tê vê wateyê: dengbêjê mezin ê ku wekî "Şahê Dengbêjan" tê naskirin û xwedî dengekî bêhempa bû.', '"Şakiro" şu anlama gelir: "Dengbêjlerin Şahı" diye bilinen, eşsiz sese sahip büyük dengbêj.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_21351
