('8d89bae8-ac07-5b59-9ac8-b1dabdf2c113', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Şêwaza kilamên dengbêjiyê ya ku bi piranî li ser evîn û hesretê ye kîjan e?', 'bilûr', 'lawik', 'Meryem Xan', 'erbane', 'B', '"lawik" tê vê wateyê: şêwaza kilama dengbêjiyê ya lîrîk ku bi piranî li ser evîn û hesretê ye.', '"lawik" tê vê wateyê: şêwaza kilama dengbêjiyê ya lîrîk ku bi piranî li ser evîn û hesretê ye.', '"lawik" şu anlama gelir: çoğunlukla aşk ve hasret üzerine söylenen lirik dengbêjlik kilamı.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_21451
